use system.gpu
use system.gpu.atomic.{Atomic}
use system.collections.array
use system.collections.list
use system.fs
use system.os

fn main()
    let args = Args()
    let fs = Fs()
    let read = fs.read_file(args.element_at(0))
    let text = match read
        Result.Ok(t): t
        Result.Err(_): panic("cannot read the parameter file")

    var fields = List<int>()
    for part in text.replace("\n", " ").replace("\r", " ").replace("\t", " ").split(" ")
        if not part.is_empty()
            fields.push(part.to_int() ?? 0)

    let count = fields.get(0)
    let seed = fields.get(1)
    let bins = fields.get(2)

    // Counts live on the GPU as atomics, one slot per possible bin.
    gpu var counts = Array<Atomic<i32>, 256>()
    let bins32 = bins as i32
    let seed32 = seed as i32

    if count > 0
        forall i in 0..count
            let k = i as i32
            let a = ((k % 40000) * 1597 + seed32 + 51749) % 40000
            let b = (a * a + a * 37 + 11) % 40009
            let c = (b * 613 + 7919) % 40009
            let d = (c + (k / 40000) * 7919) % 40009
            let value = d % 1000
            atomic_add(counts, value * bins32 / 1000, 1)

    // Read each slot back through a plain buffer; atomic_add(.., 0) returns the current count.
    gpu var plain = Array<int, 256>()
    forall b in 0..256
        plain[b] = atomic_add(counts, b, 0)

    var host = Array<int, 256>()
    host = plain

    for b in 0..bins
        println(f"BIN {b} {host.element_at(b)}")
    println(f"TOTAL {count}")

